-- APPLIQUÉE en production le 6/11/2026 (migrations site_web_et_base_comptes_schema, base_comptes_donnees, enrichir_comptes_depuis_base, grant_esi_dep_depuis_cp_anon).
-- Site web sur les comptes + base des comptes actifs enrichis (fichier Drive « BASE COMPTES ACTIFS - MATCHES ET ENRICHIS », 6/11/2026).
-- La base sert à mesurer l'enrichissement (suivi du remplissage) et à compléter les champs VIDES des comptes de l'app.
alter table public.comptes add column if not exists site_web text;

create table if not exists public.base_comptes (
  id uuid primary key default gen_random_uuid(),
  commercial text, nom text not null, type_compte text,
  adresse text, code_postal text, ville text, tel text, email text, site_web text, contact_principal text,
  statut text not null default 'A COMPLETER' check (statut in ('ENRICHI','A COMPLETER')),
  compte_id uuid references public.comptes(id) on delete set null,
  updated_at timestamptz not null default now()
);
create index if not exists base_comptes_compte_idx on public.base_comptes(compte_id);
alter table public.base_comptes enable row level security;
drop policy if exists service_role_all on public.base_comptes;
create policy service_role_all on public.base_comptes for all to service_role using (true) with check (true);
drop policy if exists lecture_session on public.base_comptes;
create policy lecture_session on public.base_comptes for select to anon, authenticated using ((select esi_session_valide()));
drop policy if exists ecriture_admin on public.base_comptes;
create policy ecriture_admin on public.base_comptes for all to anon, authenticated
  using ((select esi_role()) = any (array['ADMIN','CHANNEL_MANAGER'])) with check ((select esi_role()) = any (array['ADMIN','CHANNEL_MANAGER']));

truncate public.base_comptes;

-- Rattachement au compte de l'app : nom normalisé (sans accents, sans ponctuation), le premier nom avant « / » aussi.
create or replace function pg_temp.norm(t text) returns text language sql immutable as $$
  select regexp_replace(upper(translate(coalesce(t,''),'àâäéèêëîïôöùûüçÀÂÄÉÈÊËÎÏÔÖÙÛÜÇ','AAAEEEEIIOOUUUCAAAEEEEIIOOUUUC')),'[^A-Z0-9]','','g') $$;
update public.base_comptes b set compte_id = c.id
from (select distinct on (pg_temp.norm(nom_compte)) id, pg_temp.norm(nom_compte) n from public.comptes where coalesce(deleted,false)=false order by pg_temp.norm(nom_compte), created_at) c
where c.n = pg_temp.norm(b.nom) or c.n = pg_temp.norm(split_part(b.nom,' / ',1)) or c.n = pg_temp.norm(split_part(b.nom,' / ',2));
